	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		ProductPricing
	 */
		public ProductPricing createProductPricing( CreateProductPricingCommand command ) {

		ProductPricing entity = new ProductPricing();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setProductPricingId( command.getProductPricingId() );
            entity.setListPrice( command.getListPrice() );
            entity.setSalePrice( command.getSalePrice() );
            entity.setValidFrom( command.getValidFrom() );
            entity.setValidTo( command.getValidTo() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of ProductPricing {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateProductPricingCommand
	 * @return		ProductPricing
	 */
	public ProductPricing updateProductPricing( UpdateProductPricingCommand command ) {

		ProductPricing entity = new ProductPricing();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setProductPricingId( command.getProductPricingId() );
            entity.setListPrice( command.getListPrice() );
            entity.setSalePrice( command.getSalePrice() );
            entity.setValidFrom( command.getValidFrom() );
            entity.setValidTo( command.getValidTo() );
            entity.setVariant( command.getVariant() );
            entity.setChannel( command.getChannel() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of ProductPricing {0} ", entity.toString() );

		return entity;
	}

