	/**
	 * Method to retrieve the ProductPricing via ProductPricingFetchOneSummary
	 * @param 	summary ProductPricingFetchOneSummary
	 * @return 	ProductPricingFetchOneResponse
	 */
	public ProductPricing getProductPricing( ProductPricingFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ProductPricingFetchOneSummary arg cannot be null" );

		ProductPricing entity = null;
		UUID id = summary.getProductPricingId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a ProductPricing using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


